package target

import (
	"bytes"
	"fmt"
	"strconv"
	"strings"
)

// CopilotInstructionsDir is where GitHub Copilot and VS Code read scoped
// instructions.
const CopilotInstructionsDir = ".github/instructions"

// copilotPrefix namespaces generated files. Discovery here is a flat glob rather
// than a recursive one, so generated instructions cannot nest under a directory
// of their own; the prefix keeps them apart from hand-written ones and lets a
// single gitignore glob cover them.
const copilotPrefix = "qm-"

// copilot renders instruction files for GitHub Copilot and VS Code.
//
// It renders only rules. Copilot has no skill or agent concept, and its
// always-on instructions come from AGENTS.md, which the agents-md target owns.
// The scope mechanism is an applyTo glob, so a rule that is resident everywhere
// declares applyTo "**" and a scoped one declares its own globs.
type copilot struct{}

func (copilot) Name() string { return "copilot" }

func (copilot) IgnorePaths() []string {
	return []string{CopilotInstructionsDir + "/" + copilotPrefix + "*.instructions.md"}
}

func (copilot) Render(in Input) (Output, error) {
	files := make([]File, 0, len(in.Docs))
	for _, d := range in.Docs {
		files = append(files, File{
			Path: fmt.Sprintf("%s/%s%s.instructions.md", CopilotInstructionsDir, copilotPrefix, d.ID),
			Body: renderCopilotInstruction(d),
		})
	}
	return Output{Files: files}, nil
}

func renderCopilotInstruction(d Doc) []byte {
	var b bytes.Buffer

	b.WriteString("---\n")
	fmt.Fprintf(&b, "# Generated by Quartermaster. Do not edit; edit the source document instead.\n")
	fmt.Fprintf(&b, "# source: %s  bundle: %s", d.ID, d.Digest)
	if d.Commit != "" {
		fmt.Fprintf(&b, "  commit: %s", d.Commit)
	}
	b.WriteByte('\n')

	// applyTo takes a comma-separated glob string, and applies everywhere when
	// the document declares no scope.
	apply := "**"
	if len(d.Scope) > 0 {
		apply = strings.Join(d.Scope, ",")
	}
	fmt.Fprintf(&b, "applyTo: %s\n", strconv.Quote(apply))
	if d.Description != "" {
		fmt.Fprintf(&b, "description: %s\n", strconv.Quote(d.Description))
	}
	b.WriteString("---\n\n")

	b.Write(RuleBody(d.Prose))
	return b.Bytes()
}
